// Generated by tools/build-patch-data.mjs. Do not edit by hand. The whole patch history for the in-app Patch Notes reader and the tour library.
(function (root) { var Stick = root.Stick = root.Stick || {}; Stick.patchHistory = {"categories":["Canvas","Media","Sharing","Mobile","Privacy","Performance","Nodes"],"versions":[{"version":"0.8.3.2","slug":"v0-8-3-2","codename":"Finish the Flow","title":"Stick-It v0.8.3.2 — Finish the Flow","status":"development","date":null,"summary":"More expressive newspapers, better system-space feedback, smarter paste behavior, stronger zones and piles, and the complete Stick-It patch history inside the app.","tags":["Canvas","Nodes","Sharing","Mobile"],"highlights":["Paste it your way: text can become a sticky or a clipping, and Stick-It can remember your choice.","Zones actually organize things: collapse a whole zone, keep its contents together, and see what belongs where.","Done sounds done: a stronger completion moment, with sounds for Done, Trash and Restore.","Every patch, still here: read every patch note and replay old feature tours from inside Stick-It.","Newspaper got pictures: add an image and give it a black-and-white print treatment."],"notes":[{"heading":"Paste it your way","blocks":[{"t":"ul","items":["Choose Sticky Note or Clipping when pasting text","Remember your preferred choice","Change it later in Settings"]}]},{"heading":"Newspapers got pictures","blocks":[{"t":"ul","items":["Add an image","Replace/remove it","Switch between color and black-and-white"]}]},{"heading":"Done feels better","blocks":[{"t":"ul","items":["Slightly stronger completion effect","New Done sound"]}]},{"heading":"Trash sounds like Trash","blocks":[{"t":"ul","items":["Subtle discard sound","Restore gets its own return sound"]}]},{"heading":"Shopping Lists are editable again","blocks":[{"t":"ul","items":["Fixed the editing regression across item text/details"]}]},{"heading":"Legal got another design pass","blocks":[{"t":"ul","items":["Cleaner in-app legal reader","Better tabs, controls, document spacing and mobile layout"]}]},{"heading":"Zones became real containers","blocks":[{"t":"ul","items":["Larger/freer sizing","See which objects belong to a zone","Minimize a zone with all its contents","Restore everything safely"]}]},{"heading":"Piles look more physical","blocks":[{"t":"ul","items":["Better mixed-node presentation","Physical navigation controls","Cleaner member index"]}]},{"heading":"Smarter dates","blocks":[{"t":"ul","items":["Better natural Hebrew and English date/time phrase recognition"]}]},{"heading":"Collaboration got faster","blocks":[{"t":"ul","items":["Add multiple invite emails","Enter/comma creates email pills","Paste several addresses at once"]}]},{"heading":"Safer sign-out","blocks":[{"t":"ul","items":["Sign out now asks for confirmation"]}]},{"heading":"Tutorial keyboard navigation","blocks":[{"t":"ul","items":["Enter/Right = Next","Backspace/Delete/Left = Previous"]}]},{"heading":"Reactions got room to breathe","blocks":[{"t":"ul","items":["Reaction control no longer fights with the ... menu","Quick reactions plus a broader emoji picker","Native emoji rendering"]}]},{"heading":"Double-click your way","blocks":[{"t":"ul","items":["Choose which node double-click creates","Or ask every time"]}]},{"heading":"Receipt cleanup","blocks":[{"t":"ul","items":["Styles now live under Style","Receipts can be marked Done"]}]},{"heading":"Every patch inside Stick-It","blocks":[{"t":"ul","items":["Browse the full patch history","Read full notes","Replay old patch tutorials","Same structured patch data can power the website too"]}]}],"tour":{"mode":"full","cards":[{"title":"Finish the Flow","body":"A finishing pass for the things that should feel obvious once they exist. This takes about thirty seconds."},{"title":"Paste it your way","body":"Text can become a sticky or a clipping — and Stick-It can remember your choice. Change it any time in Settings, Shortcuts, Input.","feature":"paste","action":"openShortcuts"},{"title":"Zones actually organize things","body":"Collapse a whole zone, keep its contents together, and see at a glance which notes belong to which zone.","feature":"zones"},{"title":"Done sounds done","body":"More satisfying completion feedback, with soft sounds for Done, Trash and Restore (they follow your Sounds setting).","feature":"sounds","action":"openSounds"},{"title":"Every patch, still here","body":"Read every patch note and replay old feature tours from inside Stick-It: Settings, Legal & About, What's New.","feature":"patchNotes","action":"openPatchNotes"},{"title":"Newspaper got pictures","body":"Add an image to a Newspaper and give it a black-and-white print treatment.","feature":"newspaper"}]},"media":[],"notesFile":"0.8.3.2.md","newer":null,"older":"0.8.3.1"},{"version":"0.8.3.1","slug":"v0-8-3-1","codename":"Finish the Edges","title":"Stick-It v0.8.3.1 — Finish the Edges","status":"development","date":null,"summary":"Polish for Done, Trash, Clippings, layering, and Shopping List attachment.","tags":["Nodes","Canvas"],"highlights":["Done and Trash feel like places: a little more personality, kept quiet.","Sources finally look like sources: add, edit or remove a clipping's link, and familiar sites are recognised.","Layers mean layers: Bring forward/back now behaves the same for every kind of object.","The Shopping List Comment tab belongs to the receipt."],"notes":[{"heading":"Done feels more done","blocks":[{"t":"ul","items":["Done Space gets a slightly stronger completed identity: a brighter, warmer desk and a few faint hand-drawn motifs (a check stamp, a ribbon, a seal, a star)","The motifs are decoration only: very low contrast, never animated, and they never receive clicks"]}]},{"heading":"Trash looks like Trash","blocks":[{"t":"ul","items":["Tiny Stick-It-style trash cans, a basket and crumpled paper in the background, sparse and quiet, in light and dark","Still quiet enough to keep the content readable"]}]},{"heading":"Clippings know where they came from","blocks":[{"t":"ul","items":["Add, edit or remove a source link after creation: ••• → Source (Add / Edit / Remove, Open, Copy). The editor takes the link and an optional source title; Cancel changes nothing","\"No source link\" is now a button (a tap on a phone) that opens the editor","Only http(s) links are accepted; anything else is refused with a message"]}]},{"heading":"Better source icons","blocks":[{"t":"ul","items":["A small, extensible registry recognises ChatGPT, OpenAI, Gemini, Google, YouTube / youtu.be, BBC, GitHub, Reddit and Wikipedia (and their subdomains, such as en.m.wikipedia.org), with the site name and colour","The registry holds names and colours only: no hand-drawn copies of anyone's logo","Fallback order: known site → favicon (only if a favicon service is configured; none is by default, see below) → a letter badge → a plain link icon","A failed icon is remembered so it is not asked for again, and never breaks a clipping"]}]},{"heading":"Layering actually layers","blocks":[{"t":"ul","items":["Root cause: a selected object was forced to a very high z-index (9996, !important) while selected, so it always looked in front even after \"Send backward\". Selecting an object no longer changes where it sits; its z-index is its layer. Its controls are reachable by pointing at it or keyboard-focusing it","Also: merely clicking an object no longer raises it (it used to, which silently undid \"Send to back\"); picking it up and dragging still does","Bring forward / front, Send backward / back were checked across notes, clippings, shopping lists, photos, receipts, piles and zones"]}]},{"heading":"Shopping List polish","blocks":[{"t":"ul","items":["The Comment tab is placed from the receipt paper's own lower edge (not the whole node with the cart), a little higher and in from the left, with only a few pixels tucked under the paper","Re-placed whenever the paper changes size"]}]},{"heading":"Small UI consistency fixes","blocks":[{"t":"ul","items":["One row interaction for the Legal & policies rows and the System rows: a warm tint on hover, no underline, the arrow leans in, a clear focus ring, a stronger tint when pressed, and a dark-mode version"]}]},{"heading":"Technical notes (for the team)","blocks":[{"t":"ul","items":["**Favicons:** nothing fetches a favicon today. Asking a favicon service (or the site) would tell a third party which sites you keep clippings of, and the page's security policy would also need to allow it. The resolver is built and tested (`Stick.sources.faviconUrl`, cache with success and failure memory) and is off until `FAVICON_SERVICE` is set in `js/config.js` to an https address containing `{host}`, together with a matching `img-src` entry: an owner/privacy decision.","**Layering:** one stack, one rule: `z` is the layer. Hovering an object when nothing is selected still lifts it while the pointer is on it (as before)."]}]}],"tour":{"mode":"full","cards":[{"title":"Finish the Edges","body":"A polish pass for the new v0.8.3 surfaces. This takes about twenty seconds."},{"title":"Done and Trash feel like places","body":"Open your boards list, then Done or Trash under System. They each have a little more personality now, kept quiet so your things stay the star.","target":"#brandBtn","feature":"spaces","action":"openDone"},{"title":"Sources finally look like sources","body":"Open a clipping's ... menu, then Source, to add, edit or remove its link. 'No source link' is a button too. ChatGPT, Google, YouTube, BBC, GitHub, Reddit and Wikipedia are recognised."},{"title":"Layers mean layers","body":"Arrange, then Bring forward or Send backward. A selected object now stays exactly where its layer says, whatever else is on the board.","target":".moreBtn"},{"title":"Tiny fix, big annoyance gone","body":"The Shopping List Comment tab now hangs from the receipt itself instead of the cart's corner."}]},"media":[],"notesFile":"0.8.3.1.md","newer":"0.8.3.2","older":"0.8.3"},{"version":"0.8.3","slug":"v0-8-3","codename":"Stick Around","title":"Stick-It v0.8.3 — Stick Around","status":"development","date":null,"summary":"Trash, Done spaces, richer scraps, reactions, layering and better media — your board remembers what happened to things.","tags":["Canvas","Nodes","Sharing"],"highlights":["Done has somewhere to go: a real Done space, with a small stamp-and-confetti moment (none under reduced motion).","Trash without panic: deleting moves things to Trash first; restore them, or delete forever when you mean it.","Scraps got richer: newspaper scraps, source-linked clippings, emoji reactions.","Your board remembers more: search with next/previous and a count, proper layering, and piles you can shuffle, reorder and fan."],"notes":[{"heading":"Done has somewhere to go","blocks":[{"t":"ul","items":["Done is now a real system space (Boards list → System → Done), with its own warm look and a DONE stamp with the date","Completed objects keep their original content and state (words, place, layer, angle, pin, reactions, a shopping list’s ticks and prices)","Put back returns them to the board where they were","Any paper object can be marked Done (notes, lists, receipts, tickets, postcards, newspapers, clippings)","A small completion moment: a stamp and a few paper scraps (about half a second); none under reduced motion","Search it, and filter by Today / This week / Earlier"]}]},{"heading":"Trash without panic","blocks":[{"t":"ul","items":["Deleted objects go to Trash first, with their content, place and when you deleted them","Restore them (one, several, or all) back where they were, or Delete forever when you really mean it (always asks)","Trash has its own rougher, greyer look; it is not a shareable board and a public link never shows it"]}]},{"heading":"Shopping List finishing pass","blocks":[{"t":"ul","items":["The Comment tab is now tucked under the receipt’s paper edge in all three looks, and moves, turns and resizes with it","Done preserves every item’s state; the receipt spacing was reviewed and left as it was"]}]},{"heading":"Newspaper","blocks":[{"t":"ul","items":["A new free scrap: headline, optional subheading or byline, and body text in columns","Eight looks (Broadsheet, Tabloid, Gazette, Evening paper, Telegraph, Typewritten, Herald, Modern); a new one picks a look at random and you can change it in the menu","English and Hebrew (right-to-left follows the words); self-hosted fonts only","An image slot is **not** in this release (follow-up)"]}]},{"heading":"Clippings","blocks":[{"t":"ul","items":["A new scrap for a quote with where it came from: the words, a source title, and a checked source link (domain shown, opens safely)","Make one from the + menu, from any note (••• → Make clipping), or from the offer after you paste a long piece of text; change or remove the source, or convert it back to a plain note","The site mark is a letter drawn locally: Stick-It never contacts the source just to show a clipping"]}]},{"heading":"Reactions","blocks":[{"t":"ul","items":["React to anything with 👍 ❤️ 😂 👀 ✅ 💡 from the small + button under a selected object; click a chip to add or remove your own","Nothing is drawn on an object until it has a reaction; view-only boards can’t react"]}]},{"heading":"Better layering","blocks":[{"t":"ul","items":["Arrange → Bring to front, Bring forward, Send backward, Send to back (also in the command palette, and Bring to front / Send to back for a selection)","Only the layer changes: never a position, a pile or a zone (zones always stay at the back)"]}]},{"heading":"Search that actually takes you there","blocks":[{"t":"ul","items":["A result count and next / previous (Enter / Shift+Enter) with the result centred and highlighted","Finds checklist items, shopping items, receipts, newspapers, clippings (text, source title, domain) and papers hidden inside a pile (the pile opens at that paper)","A scope switch: Board / Done / Trash. (All boards is a follow-up.)"]}]},{"heading":"Better links and video","blocks":[{"t":"ul","items":["Links show a pointer, and the link card uses a letter mark instead of fetching the site’s icon","Video stays poster-first (nothing is fetched from the provider until you press Play); a playing video has Full screen and Stop","“Remove the image” is now a different place, shape and label from “delete the note”"]}]},{"heading":"Piles grew up","blocks":[{"t":"ul","items":["Shuffle, move a paper earlier or later, and a fan of up to nine papers on a computer; one paper at a time with arrows and swipe on a phone","Browsing is still only a view; reorder and shuffle change only the order"]}]},{"heading":"Receipt polish","blocks":[{"t":"ul","items":["A little larger by default, with two or three playful sample lines from ten examples (no OCR — deliberately)"]}]},{"heading":"Also","blocks":[{"t":"ul","items":["Smarter dates: “שישי בערב”, “מחר בבוקר”, “tomorrow evening”, “Friday night” (a part of the day only counts next to a date; the existing chip still asks)","Account photo: a pencil on the picture and a menu: Upload, Take photo (the camera only starts when you choose it, and always switches off), Remove, Cancel"]}]},{"heading":"Technical notes (for the team)","blocks":[{"t":"ul","items":["**System spaces:** Done and Trash are *views* of the board’s own objects, marked `doneAt` / `trashedAt` on the object itself (so they sync, export and reload like everything else). The sync snapshot is `notes + Done + Trash`; an object is never \"missing\" because it is done, in Trash, piled or not drawn. Delete forever (the user’s explicit act) is the only thing that removes a row.","**Collaboration:** unchanged semantics: Done and Trash are board-level states of the object (as Done always was), so a collaborator who trashes something trashes it for the board. Per-user cross-board spaces are a follow-up and need a design decision.","**Not in this release:** cross-board Done/Trash and \"All boards\" search, Newspaper image, OAuth providers (Apple / Microsoft need production configuration), link preview thumbnails and show/hide previews (they need a safe fetch path), a completion-effects preference, share-as-sticky from video, Trash auto-expiry (Trash keeps things until you delete them forever; server cleanup applies after Delete forever as before)."]}]}],"tour":{"mode":"full","cards":[{"title":"Stick Around","body":"Things don't just sit on the board anymore. This takes about thirty seconds."},{"title":"Done has somewhere to go","body":"Open your boards list: Done and Trash now live under System. Finished things keep their words, place and state, and 'Put back' returns them.","target":"#brandBtn","feature":"done","action":"openDone"},{"title":"Trash without panic","body":"Deleting a note moves it to Trash first. It isn't gone yet: restore it, or delete forever when you really mean it.","target":".note","feature":"trash","action":"openTrash"},{"title":"Scraps got richer","body":"Add a Newspaper or a Clipping from the right-click menu, and react to anything with a quick emoji from the small + button under a selected note."},{"title":"Your board remembers more","body":"Search now shows a count and takes you to each result, even inside a pile. Layer things from Arrange in the ... menu.","target":"#searchInput"}]},"media":[],"notesFile":"0.8.3.md","newer":"0.8.3.1","older":"0.8.2.2"},{"version":"0.8.2.2","slug":"v0-8-2-2","codename":"Touch the Paper","title":"Stick-It v0.8.2.2 — Touch the Paper","status":"development","date":null,"summary":"More physical controls, less menu clutter, and objects that behave a little more like the things they represent.","tags":["Canvas","Media","Nodes"],"highlights":["Pin it for real: a physical tack drops onto the paper (and falls away when you unpin).","Turn things a little sideways: rotate notes and scraps by hand, snap with Shift, or straighten.","Links can become videos: turn an existing video link into something playable without pasting it again.","Cleaner menus: Paper controls live under Paper, turning controls under Arrange, and Delete looks like Delete."],"notes":[{"heading":"Pinning finally looks like pinning","blocks":[{"t":"ul","items":["Pinned notes now use a physical tack","Pinning drops the tack onto the paper","Unpinning lets it fall away","Reduced-motion mode skips the animation","Pinned state still survives reload and sync"]}]},{"heading":"Give things a little tilt","blocks":[{"t":"ul","items":["Notes and supported objects can now be manually rotated","Shift snaps rotation into clean increments","Straighten returns an object to neutral","Rotation persists through save, sync and duplicate","Touch controls work without relying on hover"]}]},{"heading":"Video links become useful after paste","blocks":[{"t":"ul","items":["Supported video links can be converted into playable embeds even after the link already exists","Keep the original link or play it directly inside Stick-It","Embedded videos can be turned back into normal links","Original source URLs are preserved","Unsafe arbitrary iframe URLs remain blocked"]}]},{"heading":"Paper controls got their own home","blocks":[{"t":"ul","items":["Fit paper to content","Rip off empty paper","Restore full paper"]},{"t":"p","text":"now live under a compact Paper menu"}]},{"heading":"Delete looks like delete","blocks":[{"t":"ul","items":["Hovering/focusing a note's X now uses a clear destructive red treatment","Destructive actions share a consistent visual language","Dark mode included"]}]},{"heading":"Cleaner object menus","blocks":[{"t":"ul","items":["Related actions are grouped instead of dumped into one long list","Paper actions are separated from note-state actions","Arrangement controls have room to grow without turning the menu into a control panel"]}]},{"heading":"More Stick-It in Settings","blocks":[{"t":"ul","items":["Legal & Policies rows gain custom Stick-It SVGs","Language icon spacing tightened","Settings branding feels more connected to the canvas itself"]}]},{"heading":"Embedded video polish","blocks":[{"t":"ul","items":["YouTube/Vimeo embeds stay inside Stick-It","Video loading remains lazy","Original source stays accessible","Player and note controls interfere with each other less"]}]},{"heading":"Small tactile touches","blocks":[{"t":"ul","items":["Physical pin animation","Subtle paper response","Better destructive hover states","More consistent object interactions","Reduced-motion equivalents"]}]},{"heading":"Technical notes (for the team)","blocks":[{"t":"ul","items":["**Rotation model:** one stored angle, `rot`, in degrees, range -15..+15 (design range; the sync sanitiser now accepts that range). The natural random tilt a new object gets is only its starting value; turning edits the same number. Nothing is added at render time, so there is no second random angle, no compounding and no drift. Shift snaps to 5 degrees; Arrange has Rotate left / right (3 degrees) and Straighten (0). A copy or paste keeps its source's angle (it used to get a fresh random one).","**Supports rotation:** notes (including checklists), receipts, tickets, postcards, photo strips, shopping lists, photos. **Does not:** zones, piles, embedded video, audio and video recordings. Pinned items do not turn.","**Pin:** only `pinned` is stored. The tack's spot and tilt come from the object's id; the drop and fall are temporary animations. Duplicates keep their existing semantics (a copy is never pinned). Move to another board keeps the pin."]}]}],"tour":{"mode":"full","cards":[{"title":"Touch the Paper","body":"More physical controls, less menu clutter. This takes about thirty seconds."},{"title":"Pin it for real","body":"Pinning a note now looks like pinning a note. Tack included. Press P on a selected note and watch it drop.","target":".note"},{"title":"Turn things a little sideways","body":"Select a note and drag the small turn handle at its corner. Hold Shift to snap, double-click it to straighten, or use Arrange in the ... menu.","target":".note"},{"title":"Links can become videos","body":"Already pasted a video link? Click it and choose Play in Stick-It to turn it into something playable on the board."},{"title":"Cleaner menus","body":"Paper controls now live with Paper controls, and turning lives under Arrange. Delete turns red when you point at it.","target":".moreBtn"}]},"media":[],"notesFile":"0.8.2.2.md","newer":"0.8.3","older":"0.8.2.1"},{"version":"0.8.2.1","slug":"v0-8-2-1","codename":"Room to Breathe","title":"Stick-It v0.8.2.1 — Room to Breathe","status":"development","date":null,"summary":"Less chrome, clearer paperwork, and more room for the board.","tags":["Privacy","Mobile","Media"],"highlights":["More board, less browser chrome: a tighter phone header, a compact search and a one-line view-only strip.","Legal, without leaving Stick-It: read Privacy, Terms, Storage, Accessibility, Young People and Copyright inside the app, in English or Hebrew.","Links can become media: a supported video link can stay a link or become a video you play on the board.","Small things that stop being annoying: readable button hovers, a bigger desktop search, a lower Done pile, and browsing inside a pile."],"notes":[{"heading":"What changed","blocks":[],"sub":[{"heading":"More board, less browser chrome","blocks":[{"t":"ul","items":["Phones: the header is a single compact row; Search is an icon that opens a full-width field and a Cancel; keyboard-shortcut and help buttons (useless on a phone) are left out. The board starts directly under the header, whatever its height.","Shared (view-only) boards: one compact status line (board, who shared it, view only) with Report beside it; buttons that do nothing on a shared board are hidden. The row of seven legal links across the bottom is now one small **Legal** chip.","Desktop: a larger Search bar.","The Done pile sits about 16px lower."]}]},{"heading":"Legal, without leaving Stick-It","blocks":[{"t":"ul","items":["Settings → Legal & About → Legal: Privacy, Terms, Young people & parents, Storage, Accessibility, Copyright / DMCA open in a large in-app reader (document tabs, English / עברית, reading options for text size, high contrast and reduced motion, Back to top, dark mode, right-to-left). Esc closes it; focus is trapped and restored.","**One source of text.** The Markdown drafts in `docs/legal` are the only copy. `python tools/build-legal.py` generates both the standalone pages (`legal/*.html`, unchanged URLs) and `js/legal-content.js` that the reader renders. A test fails if they drift.","Accuracy pass on the reviewed documents (Privacy, Storage, Accessibility, Copyright / DMCA) and the minimum consistency fix on Young people. All still DRAFT with their owner / legal-review markers.","A Stick-It language icon (a sticky note with A, א, 中, ع) for the Language control. The inline brand word is semibold, never underlined."]}]},{"heading":"Piles you can look through","blocks":[{"t":"ul","items":["Arrows on a selected or hovered pile and an index (3 / 24); on touch, tap a pile to browse one paper at a time (arrows, swipe, Back to the pile). Browsing is only a view: nothing in the pile, and nothing synced, changes."]}]},{"heading":"Links can become media","blocks":[{"t":"ul","items":["Pasting a supported video link (YouTube, Vimeo) asks: **Keep as link** or **Show as embedded video**. A video is a normal board object (resize, move, pin, undo); the original address is kept and shown, and **Show as a normal link** reverses it. Nothing is loaded from the provider until you press Play; the player is removed again when it scrolls out of view or the object is deleted. The player address is built from a validated id, never from the pasted text."]}]},{"heading":"Small things","blocks":[{"t":"ul","items":["Button states: the generic hover tint no longer overrides a primary button's fill (Save went white-on-cream on hover). Filled buttons now have contrast-checked default / hover / active / focus / disabled tokens in light and dark."]}]}]},{"heading":"Not in this patch","blocks":[{"t":"p","text":"Whole-app translation, the custom video player, Fan view for piles, analytics. No change to sync deletion semantics."}]},{"heading":"Owner / legal review still open","blocks":[{"t":"p","text":"See `docs/legal/OWNER-ACTION-REQUIRED.md` and `docs/dev/PRE-BETA-CHECKLIST.md`."}]}],"tour":{"mode":"full","cards":[{"title":"Room to Breathe","body":"Less chrome, clearer paperwork, and more room for the board. This takes about thirty seconds."},{"title":"More board, less browser chrome","body":"On a phone the header is one tight row and Search is a small icon that opens a field when you need it. Shared boards get a compact one-line view-only strip.","target":"#searchToggle"},{"title":"A search you can find","body":"On a computer the search bar is bigger and easier to spot. It also looks inside piles.","target":"#searchInput"},{"title":"Legal, without leaving Stick-It","body":"Open Settings, then Legal & About, then Legal. Privacy, Terms, Storage, Accessibility, Young People and Copyright open right here, with language and reading options.","target":"#gearBtn","feature":"legal","action":"openLegal"},{"title":"Browse a pile","body":"Use the arrows (or tap a pile on a phone) to look through the papers one at a time. Nothing in the pile changes.","target":".pileObj"},{"title":"Links can become media","body":"Paste a supported video link and choose: keep it as a link, or show it as a video you can play on the board."},{"title":"Small things that stop being annoying","body":"Buttons stay readable when you hover them, and the Done pile sits a little lower out of the way."}]},"media":[],"notesFile":"0.8.2.1.md","newer":"0.8.2.2","older":"0.8.2"},{"version":"0.8.2","slug":"v0-8-2","codename":"Get a Grip","title":"Stick-It v0.8.2 — Get a Grip","status":"development","date":null,"summary":"More control, less friction: pin things in place, name areas of the board with zones, jump anywhere from a command palette, change your own keyboard shortcuts, and trim empty paper the way you meant.","tags":["Canvas","Nodes"],"highlights":["Pin in place: a pinned scrap can't be dragged, nudged or tidied away, but you can still edit it.","Board zones: named patches of paper behind your notes. Deleting one never deletes its notes.","Command palette (Ctrl/Cmd+K) and bookmarks for places on a board; Back and Forward remember where you looked.","Customise your keyboard shortcuts, with clear warnings for keys the browser keeps.","Comments can be deleted by their author or the board owner, enforced by the database, not just the screen.","Fit paper and Rip really measure the words, not the trailing blank lines."],"notes":[{"heading":"What changed","blocks":[{"t":"p","text":"v0.8.1 put everything in one place. v0.8.2 lets you hold it still and steer it. Things can be pinned so they stay put, areas of the board can have names, every command can be found by typing, shortcuts are yours to change, and the small annoyances that made the board fight you (paper that wouldn't trim, a tidy-up that counted wrong, a Settings dialog that closed on Save) were fixed."}]},{"heading":"New in this patch","blocks":[],"sub":[{"heading":"Holding things still","blocks":[{"t":"ul","items":["**Pin in place.** Choose it from a note's menu, or press **P**. A pinned note, photo or scrap shows a small pin, can't be dragged or nudged (even inside a group), is skipped by Clean up (which tidies around it), and can still be selected, edited, resized, marked done, moved to another board or unpinned. Pins survive reloads and sync. Duplicates, pastes and imports are never pinned.","**Board zones.** *Add a zone* from the board's right-click menu or the command palette. It is a patch of paper behind your notes with a title strip, a corner handle, a material (paper, kraft, cardboard, grid, felt) and a colour. *Move with its notes* (off by default) carries the notes lying on it when you drag it. Deleting a zone only removes the paper; the notes stay. Clean up leaves notes inside a zone where they are."]}]},{"heading":"Getting around","blocks":[{"t":"ul","items":["**Command palette** (Ctrl/Cmd+K). Type what you want: New note, Pin, Mark done, Clean my screen, Clean the whole board, Bookmark this spot, Search, Settings, What's New, and more. It is built from the same list as the shortcuts, so it always shows the key you currently use.","**Bookmarks.** Press **B** to save the spot you're looking at, then find it in the palette. *Manage bookmarks* renames or deletes them. Up to 30 per board, kept on this device.","**Back and Forward.** **Alt+[** and **Alt+]** step through the places you've looked at on a board. A place is remembered once you stay somewhere clearly different for a moment; the list is capped at 30 and lasts for the visit."]}]},{"heading":"Shortcuts that are yours","blocks":[{"t":"ul","items":["**Change any shortcut.** In Settings → Shortcuts, *Your shortcuts* lists every action that can be rebound. *Change* then press the keys; *Reset* and *Reset all to default* undo it.","**Safe by design.** A shortcut must include a real key. Keys the browser keeps (Ctrl+T, Ctrl+W…), the system keeps (Alt+Tab), text editing uses (Ctrl+C, Ctrl+Z…) or that have a fixed job (Esc, Enter, Tab, the arrows) are refused with a plain reason. If the keys are already used by another action you get *Replace* or *Cancel*. Esc cancels the prompt only.","**Saved.** On this device always; when signed in, it follows your account (a small private preferences column, capped at 8 kB).","**Dark mode.** Key caps are readable in dark mode."]}]},{"heading":"What's New","blocks":[{"t":"ul","items":["After an update you get one small card: **Show me**, **Not now**, **View patch notes**. *Show me* is a short tour that only points at things that exist on your screen. New people see the normal tutorial instead. *What's New* is always available under Settings → Legal & About and in the command palette."]}]},{"heading":"Shopping List","blocks":[{"t":"ul","items":["**One free node for anything you buy.** Add it from the Add menu (More...) or the command palette and start from **Blank**, **Groceries** or **Trip / shopping abroad**. A preset only chooses which optional details start switched on; it is never a different kind of list.","**A receipt in a cart.** The words live on a paper strip that sits in a small cart (always the same height). The paper grows with the list up to about 400 px, then the items scroll inside it. The header reads \"7 to buy · 3 in cart\", or \"7 in cart · All picked ✓\" with a small stamp when everything is in.","**Ticking.** A hand-drawn tick and a soft strike, and the item slides into *In the cart* (ordered by when you picked it up). Untick it and it goes back. *Clear bought items* is one undo step and asks first when it removes more than one.","**Optional details,** switched on per list in the ... menu under **Details**: Quantity, Note, Price, Link, Tag. All are off by default and an item only shows a detail it has. A row's small arrow opens its detail fields. Links open only from their own arrow, never while you edit.","**Money.** Currency is chosen per list (the device language suggests one, so a list made in Israel starts in ₪), nothing is converted, prices are stored as whole minor units and shown with the right number style, and the total simply adds the prices you entered (quantity is never multiplied in).","**Done is separate.** Ticking items never marks the list Done. *Mark list done* in the menu sends the whole list to the Done pile, and Put back restores every item and tick exactly as it was.","Up to 100 items per list. Works in dark mode, on touch (bigger tap targets), in shared views (read-only), and with search, duplicate, move, pin and Undo."]}]},{"heading":"Writing in notes","blocks":[{"t":"ul","items":["**Underline.** Ctrl/Cmd+U (or the U button in the note menu, the focus-mode strip and the selection toolbar) underlines. Links look different on purpose: coloured, with a dotted line and a small arrow.","**Selection toolbar.** Highlight words in a note and a small Stick-It toolbar appears above them: Bold, Italic, Underline, Highlight, Link.","**Checklist titles.** A first line that ends with a colon becomes a title with no checkbox when you make a checklist. Any line can be switched with the *Title line* button. Titles are never counted as unfinished.","**Pull a note longer.** Drag the bottom edge to make a note longer, or the right edge to make it wider. On a touch screen the selected note shows a wide grab bar to drag with a finger."]}]},{"heading":"Comments","blocks":[{"t":"ul","items":["**Delete.** You can delete your own comment; the board owner can delete anyone's. Other collaborators, viewers and signed-out visitors can't, and that rule is enforced by the database itself. A branded confirmation replaces the browser's own popup. The comment slip is more compact."]}]},{"heading":"Legal & info","blocks":[{"t":"ul","items":["**Reading options** on every legal page: text size (small, default, large), high contrast, reduce motion, and beige or dark. They are remembered on this device and shared with the app.","**Beige by default.** The notebook page is beige unless you chose dark (in the app or on the page).","**Language chooser.** A globe replaces the loose \"עברית\" link. It lists only languages whose pages are complete (English and Hebrew today) and the same list can serve the app later.","**One type scale** for all six pages in both languages."]}]}]},{"heading":"Fixed","blocks":[{"t":"ul","items":["Clean up could count one set of notes and move another. It now takes one fixed list when you open it and uses it for the count, the move and the undo.","Fit paper and Rip off empty paper counted trailing blank lines and empty Shift+Enter breaks as content. They now measure the words.","The \"New board links\" row lit up its entire row on hover.","A comment's delete button no longer crowds its text.","Select-all and the new-note key stopped working for a moment while the shortcut list was being rebuilt; fixed before this patch ships."]},{"t":"ul","items":["**Shared links.** The page for a link that can't be opened used to say \"Couldn't reach the server\" for almost anything. It now says what is true: no connection, a server problem, never existed, turned off by the owner, or invited-only. Recoverable problems get **Try again** (with the small loader, one request at a time) next to **Open Stick-It**, a request that stalls gives up after 15 seconds, and one transient failure is retried quietly first. A short code (such as 502) shows under the message for support; nothing internal is shown."]}]},{"heading":"Improved","blocks":[{"t":"ul","items":["**Trim empty paper?** After you stop typing in a note with lots of empty paper, a quiet offer appears (never automatic, once per note per visit).","**Settings.** Save keeps you where you are and says *Saved*. Appearance has more controls (shadow depth, paper texture, tilt, tape, dots, compact, reduce motion, high contrast) with a live preview; Cancel puts everything back.","**Esc** closes only the topmost temporary thing: the palette, the tour, comments, the board picker, a menu, the rebinder, the language list, a dialog.","**Sound preview** animates while it plays.","**Account.** The plan chip opens a short explanation on hover, focus or tap; the storage bar shows used and remaining in words and in the bar; the crown is a crisp vector in dark mode.","**Buttons** share one quiet hover and press feel and respect reduced motion.","**Clean up** button is a broom."]}]},{"heading":"Still being worked on","blocks":[{"t":"ul","items":["**Resolved:** a shared-board link opened from a local copy on port 8124 showed \"Couldn't reach the server\". The share functions only allowed port 8123; they now allow local development on any port (redeployed). The live site was never affected. Earlier note: one report of a shared-board link showing \"Couldn't reach the server\". On the live site, signed out and with empty storage, a live-board link, a snapshot link, a turned-off link and an unknown link all behaved correctly, and the server answered 200/410/404 as designed. The cause was not found; the new messages and the status code are there to identify it if it happens again. A possible contributor: GitHub Pages lets browsers keep scripts for up to ten minutes, so right after a deploy a visitor can briefly run old and new files together.","The two new migrations are applied to the real project (confirmed with `npx supabase migration list`, and the functions refuse signed-out callers). Signed-in behaviour against the real project (comment delete by author/owner/others, shortcut sync) is **not yet tested**: it needs real accounts.","Bookmarks are per device; they don't sync yet.","Zones don't have an \"arrange inside this zone\" action.","The legal text is still a draft and has not been reviewed by a lawyer.","Not checked: signed-in plan popover, storage bar and crown against a real account; a physical phone; a screen reader; real Realtime with two accounts; the Done pile across devices.","The memory audit now also covered 20 photos, 4 videos, 5 voice memos and a zone (delete, undo, three times: no growth). Cutouts and live collaboration were not measured. One real leak was found and fixed: a deleted voice memo or video kept its object URL, and so its file, in memory until the page reloaded."]}]}],"tour":{"mode":"full","cards":[{"title":"Get a Grip","body":"A few things changed so the board does what you meant. This takes about thirty seconds."},{"title":"Clean up, counted honestly","body":"The numbers now match what actually moves. Pinned notes and notes inside a zone stay exactly where they are, and one Undo puts everything back.","target":"#cleanBtn"},{"title":"Shortcuts are yours","body":"Open Shortcuts and press Change on any row to give it your own keys. Ctrl/Cmd+K opens the command palette: type what you want to do.","target":"#kbdBtn"},{"title":"Look and feel, with a preview","body":"Appearance now has more controls and shows them live. Save keeps you where you are and says Saved.","target":"#gearBtn"},{"title":"Pin in place","body":"Open a note's ••• menu and choose Pin in place (or press P). It stays put while you move things around it.","target":".note"},{"title":"Zones and bookmarks","body":"Right-click the board and add a Zone to name an area. Press B to bookmark the spot you're looking at, and Alt+[ to go back.","target":"#boardInner"}]},"media":[],"notesFile":"0.8.2.md","newer":"0.8.2.1","older":"0.8.1"},{"version":"0.8.1","slug":"v0-8-1","codename":"One Place","title":"Stick-It v0.8.1 — One Place","status":"development","date":null,"summary":"Settings finally stopped living in six different places: account, appearance, sharing, privacy, sounds and shortcuts now share one roof. Notes get a quick done tick and a way to trim empty paper, and the board gets a tidy-up button.","tags":["Canvas","Privacy","Performance"],"highlights":["One settings home for account, appearance, sharing, privacy and data, sounds, shortcuts and legal, with one Save and one Cancel.","Clean up: tidy what's on your screen or the whole canvas, never delete a thing, and undo it in one step.","A quick done tick beside the x on every note.","Fit paper to content, Rip off empty paper, and a quiet corner handle to resize a note.","Comments hang off the note like a clipped paper slip."],"notes":[{"heading":"What changed","blocks":[{"t":"p","text":"v0.8.0 made Stick-It do more. v0.8.1 makes it feel like one place. The scattered account, settings, shortcut and legal screens became a single Control Center, notes got friendlier hands (a done tick, trimming, resizing), the board learned to tidy itself on request, and a handful of rough edges from v0.8.0 got sanded down."}]},{"heading":"New in this patch","blocks":[],"sub":[{"heading":"One settings home","blocks":[{"t":"ul","items":["**Control Center.** One dialog for Account, Appearance, Sharing, Privacy & Data, Sounds, Shortcuts and Legal & About. A left rail on computers, a scrolling tab strip on phones, real keyboard-friendly tabs.","**Opens where you meant.** The avatar opens Account, the gear opens Appearance, the keyboard button opens Shortcuts. Same dialog, no duplicated content.","**One Save, one Cancel.** Preferences and your profile are staged together. Export, Sign out, Delete account and share-link actions stay immediate.","**Sounds.** A sound-effects switch, a volume slider and a soft preview. Stick-It doesn't play sounds yet; this remembers your choice for when it does."]}]},{"heading":"Canvas controls","blocks":[{"t":"ul","items":["**Clean up.** A new button in the top bar. *Clean my screen* tidies only what you're looking at; *Clean whole canvas* tidies everything. It shows how many items it will move, never deletes anything, keeps size and tilt, avoids overlaps, and is one undo step.","**Status slip.** A small red-note slip at the foot of the board says what Stick-It is up to (syncing, loading photos or media, preparing a share, exporting). It only appears when something is actually slow, and never blocks the board."]}]},{"heading":"Notes & Done","blocks":[{"t":"ul","items":["**Quick done tick** beside the x on notes and checklists. The note slides into the Done pile.","**Fit paper to content** shrinks a note around its words. **Rip off empty paper** tears the unused part away (torn, cut or notebook edge) and leaves a small scrap. **Restore full paper** undoes either. All three are undoable.","**Resize a note** with a quiet corner handle on the selected note. Text is never scaled and never clipped."]}]},{"heading":"Comments","blocks":[{"t":"ul","items":["A small **Comments · 2** tab hangs off the bottom edge of the object, and the thread opens as a compact paper slip underneath it: avatar, name, time, words, and a quiet delete. Your own comments show your own picture."]}]},{"heading":"Loading","blocks":[{"t":"ul","items":["Active Shares, comments and the username check use the Stick-It loader (with a Try again when something fails) instead of plain \"Loading…\"."]}]},{"heading":"Shortcuts","blocks":[{"t":"ul","items":["A searchable cheat-sheet of small key caps, grouped as Selecting & moving, Editing, Board, Media, Navigation and Cutout Maker."]}]},{"heading":"Legal & info","blocks":[{"t":"ul","items":["The legal pages are written on a spiral-notebook page (ruled lines, margin, binding, sticky-note callouts), in English and Hebrew, light and dark. The words and every disclosure are unchanged."]}]},{"heading":"Performance","blocks":[{"t":"ul","items":["The Control Center opens in a few milliseconds; Shortcuts, Legal and Sounds are built only when first opened, and account numbers are fetched only when a section that shows them opens."]}]}]},{"heading":"Fixed","blocks":[{"t":"ul","items":["Typing in Bio (or Name) no longer rebuilds the profile picture.","Pasted text no longer arrives highlighted or a line too low (browsers wrap copied text in invisible styling; Stick-It now strips it).","Alphabet Soup no longer wears a strip of washi tape.","Comment layout: author, time and delete no longer fight the comment's words.","Premium looked different in different places (a crown on the header avatar, plain words in the account screen); the crown now sits on the avatar wherever an avatar is large enough."]}]},{"heading":"Improved","blocks":[{"t":"ul","items":["The email-updates row is one short line: \"Occasional Stick-It news and feature updates. You can unsubscribe anytime.\"","The profile avatar and the sharing preview are only redrawn when the picture itself changes.","A selected note's ✕ shows without hovering."]}]},{"heading":"Still being worked on","blocks":[{"t":"ul","items":["The Control Center was checked against a local stand-in for the account service. It has not been used against the real project yet.","Other people's pictures don't appear next to their comments (initials only, on purpose).","Switching boards and first sign-in still use the full-screen loader, because the page reloads.","Reduced motion and screen readers were not tested in a real browser setting.","Finished notes still count toward a board's object limit."]}]}],"tour":{"mode":"derived","cards":[{"title":"One settings home for account,","body":"One settings home for account, appearance, sharing, privacy and data, sounds, shortcuts and legal, with one Save and one Cancel."},{"title":"Clean up","body":"tidy what's on your screen or the whole canvas, never delete a thing, and undo it in one step."},{"title":"A quick done tick beside","body":"A quick done tick beside the x on every note."},{"title":"Fit paper to content, Rip","body":"Fit paper to content, Rip off empty paper, and a quiet corner handle to resize a note."},{"title":"Comments hang off the note","body":"Comments hang off the note like a clipped paper slip."}]},"media":[],"notesFile":"0.8.1.md","newer":"0.8.2","older":"0.8.0"},{"version":"0.8.0","slug":"v0-8-0","codename":"Cut It Out","title":"Stick-It v0.8.0 — Cut It Out","status":"development","date":null,"summary":"Photos can now be cut out right on your device, you can right-click the board to add things, and the corkboard gains receipts, tickets, postcards, photo strips and a bowl of alphabet soup.","tags":["Media","Nodes","Sharing","Privacy"],"highlights":["Real on-device cutouts with a Cutout Maker (Erase, Restore, Refine) and sticker or mounted looks.","Right-click the board to add things.","Receipts, tickets, postcards and photo strips.","Alphabet Soup, a Premium cosmetic.","A Done pile for finished notes.","Quiet collaboration: presence, comments and review states."],"notes":[{"heading":"Highlights","blocks":[{"t":"ul","items":["**Real cutouts.** Pick a photo, let Stick-It cut the subject out (people, pets, buildings, products, plants), then Erase, Restore or Refine the edge. The cutout fills the editor so you can see what you're doing, and your original photo is never touched. Your photo never leaves your device to make a cutout.","**Sticker and mounted looks.** A white scissor border (none, thin or medium), or the cutout glued onto light cardboard, kraft, white paper, notebook paper or graph paper.","**Right-click to add.** On a computer, right-click empty board for a small menu: note, photo, cutout photo, receipt, ticket, postcard, photo strip, recording, video, alphabet soup. On a phone, tap the desk and choose More.","**New scraps.** Receipts and tickets (with an honest \"decorative numbers only\" promise), postcards you can turn over, instant-film photo strips made from photos already on your board.","**Alphabet Soup.** A Premium cosmetic: a real bowl of soup with your words floating in it as pasta letters. Everyone can see it; only Premium accounts can make it (nothing to buy yet).","**A Done pile.** Finished notes slide into a small stack at the edge of the board instead of cluttering it. Read them, put them back, or throw them away.","**Working together, quietly.** Small initials show who is on a shared board, a note someone is editing says so, and comments and a lightweight \"changes requested / ready for review\" step stick to objects, never to the empty board."]}]},{"heading":"Added","blocks":[{"t":"ul","items":["On-device cutout engine (U²-Net family, WebAssembly) and the Cutout Maker: a big canvas that frames the subject, Erase, Restore, Refine (smooth, soften, trim), brush size, zoom, pan, Fit subject / Fit original, local undo/redo, a white-border choice, Retry (a second look) and a clear failure state.","Receipt, Ticket, Postcard and Photo Strip objects, each with a few restrained variants.","Photo strips from 2-6 existing photos (Make photo strip, with a small picker if you need to choose), or from files; a strip editor (order, add, remove, caption).","Alphabet Soup cosmetic (Premium, enforced by the server as well as the app).","Right-click insertion menu and object menus; \"Comment…\" in object menus on shared boards.","Presence initials, active-object badges, an expiring \"someone is editing this note\" lock.","Comments (object-attached, on a small clipped paper slip) and review state, with a \"Request changes\" slip.","Done pile: Mark done on a note, a Done · N stack at the board's edge, a tray to read, put back or delete.","Focus Mode formatting strip: bold, italic, headings, highlight, lists, checklist and link without opening the \"…\" menu.","Recordings show elapsed / duration and a waveform that fills as it plays; recordings and videos can be resized; videos play right on the board (and can still be opened large).","Drag the highlighted window on the minimap to pan the board.","Captions and small labels use a short list of clear, readable handwriting-style fonts for every script (note fonts are unchanged).","Three typewriter fonts for receipts and tickets (Cutive Mono, Courier Prime, Special Elite), self-hosted."]}]},{"heading":"Improved","blocks":[{"t":"ul","items":["While one object is selected the rest of the board stays still (no lifting, no swaying), and the selected object stays on top.","Clicking the text of a selected receipt, ticket or postcard edits it, and the text cursor appears where you can type.","Boards with many photos use much less memory: pictures are drawn from small previews while the originals stay untouched.","Board thumbnails and shared/exported pictures draw real cutouts by their outline.","Postcards in shared views turn over when tapped.","Editor role on shared boards is now recognised correctly in \"Move to board\".","Guest boards now bring receipts, postcards, strips and cutouts along when signing in."]}]},{"heading":"Changed","blocks":[{"t":"ul","items":["The desktop hint now says \"Right-click anywhere to add something\" (double-click still makes a note).","`script-src` gained `'wasm-unsafe-eval'` (needed for WebAssembly; it does not allow JavaScript `eval`).","Questions and problems use Stick-It's own dialogs everywhere; no browser pop-ups remain."]}]},{"heading":"Fixed","blocks":[{"t":"ul","items":["A duplicated cutout now draws as soon as its copy exists.","First-run cutout failures show the \"Couldn't make a clean cutout\" panel instead of a half-empty editor.","Dragging a note no longer rebuilds the whole minimap on every pixel of movement."]}]},{"heading":"Collaboration","blocks":[{"t":"ul","items":["Presence uses a private Realtime channel per board (`board:<id>`), limited to that board's members by database policy.","Comments: editors and owners write, everyone on the board reads. Review: owners request changes and resolve; editors mark ready for review."]}]},{"heading":"Privacy & Security","blocks":[{"t":"ul","items":["Cutouts never leave the device. No provider, no API key, no secret in the browser.","New policy text: comments, review state and presence are listed in the Privacy Policy and storage notice (English and Hebrew).","Every new text field is plain text and always written with `textContent`; control characters and bidi overrides are stripped; shared views are sanitised the same way.","The Premium cosmetic is checked by the database, not only by the app.","Finished notes keep who finished them (signed-in people only) and when, stored with the note."]}]},{"heading":"Known Limitations","blocks":[{"t":"ul","items":["Cluttered or ambiguous scenes do not cut out cleanly; the editor says so and offers manual tools or \"Use original\".","Cutouts run single-threaded in WebAssembly: about 2-3 seconds for the first try.","Touch editing (finger Erase/Restore, two-finger pan and pinch) is built and checked in an emulated phone viewport; it has not been tried on a physical device.","Presence and the soft lock are verified with a local two-tab transport and unit tests; the live Supabase Realtime transport and its authorization policy have not been exercised against a real project yet.","Strip pictures are reordered with arrow buttons, not by dragging.","The \"someone is editing\" lock covers note text and the text fields of the new scraps, not photo captions.","Alphabet Soup shows letters for the first 100 characters (fewer in a small bowl); the full words are always in the note and in Focus Mode.","Finished notes still count toward a board's object limit."]}]}],"tour":{"mode":"derived","cards":[{"title":"Real on-device cutouts with a","body":"Real on-device cutouts with a Cutout Maker (Erase, Restore, Refine) and sticker or mounted looks."},{"title":"Right-click the board to add","body":"Right-click the board to add things."},{"title":"Receipts, tickets, postcards and photo","body":"Receipts, tickets, postcards and photo strips."},{"title":"Alphabet Soup, a Premium cosmetic.","body":"Alphabet Soup, a Premium cosmetic."},{"title":"A Done pile for finished","body":"A Done pile for finished notes."},{"title":"Quiet collaboration","body":"presence, comments and review states."}]},"media":[],"notesFile":"0.8.0.md","newer":"0.8.1","older":null}]}; })(typeof window !== "undefined" ? window : globalThis);
